import{_ as s,o as n,c as e,a3 as t}from"./chunks/framework.CqzWVxDX.js";const l="/ems_simulate/assets/iec104-message.CVEw2CO-.png",u=JSON.parse('{"title":"IEC 60870-5-104 报文查看","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec104/packet-view.md","filePath":"guide/protocols/iec104/packet-view.md","lastUpdated":1786981506000}'),i={name:"guide/protocols/iec104/packet-view.md"};function r(p,a,d,o,c,b){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="iec-60870-5-104-报文查看" tabindex="-1">IEC 60870-5-104 报文查看 <a class="header-anchor" href="#iec-60870-5-104-报文查看" aria-label="Permalink to &quot;IEC 60870-5-104 报文查看&quot;">​</a></h1><h2 id="进入报文查看" tabindex="-1">进入报文查看 <a class="header-anchor" href="#进入报文查看" aria-label="Permalink to &quot;进入报文查看&quot;">​</a></h2><ol><li>在左侧设备树中选中 IEC104 设备；</li><li>点击右侧上方的&quot;<strong>报文</strong>&quot;图标；</li><li>窗口中实时展示 APDU 帧，支持暂停、筛选、报文详情与原始字节定位。</li></ol><p><img src="'+l+`" alt=""></p><h2 id="apdu-基本结构" tabindex="-1">APDU 基本结构 <a class="header-anchor" href="#apdu-基本结构" aria-label="Permalink to &quot;APDU 基本结构&quot;">​</a></h2><p>每条 APDU 由 <strong>启动字符 + 长度 + 控制域 +（可选）ASDU</strong> 组成：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┬──────────┬──────────────┬───────────────┐</span></span>
<span class="line"><span>│ 启动字符 68H │ 长度 L    │ 控制域 4 字节  │ ASDU（I 帧）   │</span></span>
<span class="line"><span>└──────────┴──────────┴──────────────┴───────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>启动字符：固定 <code>0x68</code>；</li><li>长度：控制域 + ASDU 的字节数（U/S 帧无 ASDU，长度为 4）；</li><li>控制域：标识帧类型与序号。</li></ul><h2 id="三类帧" tabindex="-1">三类帧 <a class="header-anchor" href="#三类帧" aria-label="Permalink to &quot;三类帧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>帧类型</th><th>控制域特征</th><th>用途</th></tr></thead><tbody><tr><td><strong>U 帧</strong></td><td>第 1 字节为 <code>0x07</code>（STARTDT）/ <code>0x0B</code>（STOPDT）/ <code>0x43</code>（TESTFR）</td><td>链路控制：启动/停止/测试</td></tr><tr><td><strong>S 帧</strong></td><td>第 1 字节低 4 位为 1（如 <code>0x01</code>）</td><td>对 I 帧的接收确认</td></tr><tr><td><strong>I 帧</strong></td><td>第 1 字节低 1 位为 0</td><td>携带 ASDU 数据</td></tr></tbody></table><h2 id="asdu-结构" tabindex="-1">ASDU 结构 <a class="header-anchor" href="#asdu-结构" aria-label="Permalink to &quot;ASDU 结构&quot;">​</a></h2><p>I 帧的数据部分为 ASDU（应用服务数据单元）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬────────────┬──────────┬──────────────┬──────────────────┐</span></span>
<span class="line"><span>│ 类型标识      │ 可变结构限定词 │ 传送原因   │ 公共地址 COA   │ 信息对象（1..N 个） │</span></span>
<span class="line"><span>│ 1 字节       │ 1 字节      │ 2 字节    │ 2 字节        │                  │</span></span>
<span class="line"><span>└──────────────┴────────────┴──────────┴──────────────┴──────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>类型标识</td><td>如 <code>0x0D</code>（13 = M_ME_NC_1 短浮点遥测）</td></tr><tr><td>可变结构限定词</td><td>信息对象数量 + 寻址方式（连续/单一）</td></tr><tr><td>传送原因</td><td>周期（1）、背景（2）、自发（3）、总召唤（20）、命令确认等</td></tr><tr><td>公共地址</td><td>站地址（COA）</td></tr><tr><td>信息对象</td><td>信息体地址（IOA）+ 值 + 品质描述符 + 时标</td></tr></tbody></table><h2 id="请求-响应示例" tabindex="-1">请求 / 响应示例 <a class="header-anchor" href="#请求-响应示例" aria-label="Permalink to &quot;请求 / 响应示例&quot;">​</a></h2><p><strong>总召唤请求（C_IC_NA_1）</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>68 0E 00 00 00 00 64 01 06 00 01 00 00 00 00 14</span></span>
<span class="line"><span>│  │  │  │  │  │  │  │  │  │  │  │  └───────── 召唤限定词 0x14（全部数据）</span></span>
<span class="line"><span>│  │  │  │  │  │  │  │  │  │  │  └──────────── 信息体地址 0</span></span>
<span class="line"><span>│  │  │  │  │  │  │  │  │  │  └─────────────── 公共地址 0x0001</span></span>
<span class="line"><span>│  │  │  │  │  │  │  │  │  └────────────────── 传送原因 6（激活）</span></span>
<span class="line"><span>│  │  │  │  │  │  │  │  └───────────────────── 可变结构限定词 01（1 个对象）</span></span>
<span class="line"><span>│  │  │  │  │  │  │  └──────────────────────── 类型标识 0x64（100 = 总召唤）</span></span>
<span class="line"><span>│  │  │  │  │  │  └─────────────────────────── 控制域：发送序号 0</span></span>
<span class="line"><span>│  │  │  │  │  └────────────────────────────── 控制域 3 字节</span></span>
<span class="line"><span>│  │  │  │  └───────────────────────────────── 长度 = 14</span></span>
<span class="line"><span>│  │  │  └──────────────────────────────────── 启动字符 68H</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>总召唤确认</strong>：传送原因 7（激活确认），随后服务端以传送原因 20（响应总召唤）上送各测点 I 帧。</p><h2 id="报文解析功能" tabindex="-1">报文解析功能 <a class="header-anchor" href="#报文解析功能" aria-label="Permalink to &quot;报文解析功能&quot;">​</a></h2><p>平台自动解析并展示：</p><ul><li><strong>帧类型</strong>：U / S / I 帧；</li><li><strong>类型标识</strong>：ASDU 名称（如 <code>M_ME_NC_1</code>）；</li><li><strong>传送原因</strong>：周期、自发、总召唤等；</li><li><strong>信息对象</strong>：信息体地址、测量值（按系数换算）、品质描述符（IV/NT/SB/BL/OV 含义）；</li><li><strong>序号</strong>：I 帧的发送/接收序号（用于滑动窗口分析）。</li></ul><h2 id="排查技巧" tabindex="-1">排查技巧 <a class="header-anchor" href="#排查技巧" aria-label="Permalink to &quot;排查技巧&quot;">​</a></h2><ul><li><strong>链路无法建立</strong>：检查是否有 U 帧 STARTDT 激活与确认；</li><li><strong>数据不刷新</strong>：查看 I 帧是否周期性上送、S 帧确认是否正常；</li><li><strong>窗口拥塞</strong>：发送序号与确认序号差距接近 k 值说明接收方未及时确认；</li><li><strong>品质无效</strong>：查看 QDS 的 IV 位是否置位。</li></ul>`,23)])])}const g=s(i,[["render",r]]);export{u as __pageData,g as default};
